document.addEventListener("DOMContentLoaded",function(){const hamburgerMenu=document.getElementById("hamburger-menu"),sidebar=document.querySelector(".sidebar"),sidebarOverlay=document.getElementById("sidebar-overlay");hamburgerMenu&&sidebar&&sidebarOverlay&&(hamburgerMenu.addEventListener("click",function(){hamburgerMenu.classList.toggle("active"),sidebar.classList.toggle("active"),sidebarOverlay.classList.toggle("active"),sidebar.classList.contains("active")?document.body.style.overflow="hidden":document.body.style.overflow=""}),sidebarOverlay.addEventListener("click",function(){hamburgerMenu.classList.remove("active"),sidebar.classList.remove("active"),sidebarOverlay.classList.remove("active"),document.body.style.overflow=""}),window.addEventListener("resize",function(){window.innerWidth>768&&(hamburgerMenu.classList.remove("active"),sidebar.classList.remove("active"),sidebarOverlay.classList.remove("active"),document.body.style.overflow="")}));const animatedBg=document.querySelector(".animated-bg"),foodItems=["\u{1F355}","\u{1F354}","\u{1F35F}","\u{1F32E}","\u{1F363}","\u{1F35C}","\u{1F371}","\u{1F957}","\u{1F372}","\u{1F35D}","\u{1F35B}","\u{1F364}","\u{1F357}","\u{1F969}","\u{1F356}","\u{1F9C1}","\u{1F370}","\u{1F36A}","\u{1F958}","\u{1F373}","\u{1F95E}","\u{1F9C7}","\u{1F96F}","\u{1F35E}","\u{1F956}","\u{1F968}","\u{1F9C0}","\u{1F951}","\u{1F345}","\u{1F955}","\u{1F336}\uFE0F","\u{1FAD2}","\u{1F96C}","\u{1F952}","\u{1F33D}"];for(let i=0;i<30;i++)setTimeout(()=>createFoodItem(),i*500);setInterval(createFoodItem,1500);function createFoodItem(){const food=document.createElement("div");food.className="food-item";const randomFood=foodItems[Math.floor(Math.random()*foodItems.length)];food.textContent=randomFood;const size=Math.floor(Math.random()*35)+25,left=Math.floor(Math.random()*100),animationDuration=Math.floor(Math.random()*12)+12,delay=Math.floor(Math.random()*8),opacity=Math.random()*.4+.6;food.style.cssText=`
                    left: ${left}%;
                    font-size: ${size}px;
                    animation-duration: ${animationDuration}s;
                    animation-delay: ${delay}s;
                    --max-opacity: ${opacity};
                `,animatedBg.appendChild(food),setTimeout(()=>{food.parentNode===animatedBg&&animatedBg.removeChild(food)},(animationDuration+delay)*1e3)}const glassCard=document.querySelector(".glass-card");document.addEventListener("mousemove",function(e){if(window.innerWidth>768){const{clientX,clientY}=e,{innerWidth,innerHeight}=window,xPercent=(clientX/innerWidth-.5)*2,yPercent=(clientY/innerHeight-.5)*2;glassCard.style.transform=`
                        perspective(1000px) 
                        rotateY(${xPercent*2}deg) 
                        rotateX(${-yPercent*2}deg)
                        translateZ(0)
                    `}}),document.addEventListener("mouseleave",function(){glassCard.style.transform="perspective(1000px) rotateY(0deg) rotateX(0deg) translateZ(0)"})});
